# coding: utf-8
from lesson_authoring import entry as E
from author_batch200_root_prec_a import B
D=B+[['拉丁 de- + precari → deprecari','祈求某事离开、祈求免于某事'],['英语 deprecate','反对、不赞成；技术上不建议继续使用']]
TECH='https://developer.mozilla.org/en-US/docs/MDN/Writing_guidelines/Experimental_deprecated_obsolete'
W=[
E('deprecate','/ˈdeprəkeɪt/','不赞成、反对〔正式〕；将功能标为不建议使用','原来是祈求坏事别发生，后来是明确表示不赞成；技术文档中是建议别再采用。','借自拉丁 deprecatus，deprecari 的分词；de-“离开”+ precari“祈求”。不是 depreciate“贬值”少写了一个 i 的错误形式。',D,'一般文章里 deprecate a practice 是反对某种做法。软件里 deprecate a feature 是宣布不再推荐使用某功能：它可能暂时还能运行，便于旧系统过渡。实际是否移除、何时移除，要看该项目说明，不能仅凭这个词判断。','deprecate a practice；deprecate a feature；the method is deprecated。','deprecate 是不赞成或不推荐使用，depreciate 是价值下降或贬低；软件 deprecated 也不等于 deleted。',('The editor deprecated the use of anonymous personal attacks.','编辑不赞成使用匿名人身攻击的做法。'),('The team decided to deprecate the old interface before removing it.','团队决定在移除旧接口之前，先将其标为不建议继续使用。'),sources=['https://www.etymonline.com/word/deprecate',TECH]),
E('deprecation','/ˌdeprəˈkeɪʃən/','不赞成、贬抑；弃用声明或过程〔技术〕','把“不推荐这样做”这件事作为一个动作、态度或流程来讨论。','经法语或直接借自拉丁 deprecatio，接 deprecari；英语名词有独立借入历史。现代对应 deprecate 的名词用法，技术义由不推荐使用发展而来。',B+[['拉丁 deprecari → deprecatio','祈求免于某事 → 这种祈求'],['法语 deprecation／拉丁名词 → 英语 deprecation','不赞成、贬抑 → 技术上的弃用']],'a deprecation warning 是提醒某种写法或功能不再推荐使用。它与程序已经崩溃不是同一回事，常用于提醒迁移。较普通的文学或正式语境中，deprecation 也可指不赞成或贬低的态度，不必每次都想到代码。','a deprecation warning；deprecation of an API；express deprecation。','deprecation 是弃用、不赞成，depreciation 是折旧或贬值。少看一个 i 就可能把软件文档误读成会计术语。',('The update displays a deprecation warning when the old method is called.','调用旧方法时，更新后的程序会显示弃用警告。'),('Her deprecation of the proposal was clear from the first paragraph.','从第一段就能看出她不赞成这个提议。'),sources=['https://www.etymonline.com/word/deprecation',TECH]),
E('deprecated','/ˈdeprəkeɪtɪd/','已不建议使用的、已弃用的〔技术常见〕；受到反对的','仍可能在那里，但已经被告知新工作最好别再依赖它。','deprecate + -ed，过去式或过去分词；作为技术状态形容词，来自“不推荐使用”的动词义。',D+[['英语 deprecate → deprecated','被标为不再推荐使用']],'deprecated function 往往不是“这个函数现在完全不能用”，而是维护者建议转用替代方案。它是否继续保留，取决于项目的兼容承诺。普通文字中也可说某种做法 was deprecated，意思是受到反对或不赞成。','a deprecated function；a deprecated API；marked as deprecated；deprecated in this release。','deprecated 是不再推荐，removed 是已移除；两个阶段可能先后发生，也可能长期停留在 deprecated。',('The deprecated function still works, but the manual recommends a replacement.','这个已弃用的函数仍能工作，但手册推荐改用替代方案。'),('The old practice was deprecated by several members of the committee.','委员会的几位成员对旧做法表示了反对。'),sources=['https://en.wiktionary.org/wiki/deprecated',TECH]),
E('deprecating','/ˈdeprəkeɪtɪŋ/','表示不赞成或贬低的；正在宣布弃用','用一句话或一个神态，把某件事的价值压低，或表示不认同。','deprecate 去 e 加 -ing；可作动词形式，也可作描写态度的形容词。',D+[['英语 deprecate → deprecating','不赞成、贬抑 → 表现这种态度的']],'a deprecating remark 是带不赞成或贬低意味的话。a deprecating smile 若是回应别人夸奖，有时是谦逊地把自己的功劳说小；若是针对别人的建议，则可能是轻视。对象和语境决定态度，不要只翻成一个固定的“嘲讽”。','a deprecating remark；a deprecating smile；a deprecating tone；deprecating an old API。','deprecating 多是态度或正在进行的动作，deprecated 多是已经被标为不推荐的状态；两者词尾承担不同角色。',('He made a deprecating remark about his own cooking.','他用一句自嘲的话贬低了自己的厨艺。'),('Her deprecating comments discouraged the new volunteers.','她那些贬低人的评论让新志愿者很泄气。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/deprecating','https://en.wiktionary.org/wiki/deprecating'])]
